package store

import (
	"context"
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"reflect"
	"sort"
	"time"

	"github.com/google/uuid"
)

// AmountCorrectionValue is one complete monetary value. A nil Amount means
// explicitly unknown; a nil enclosing *AmountCorrectionValue means unchanged.
// Input Basis may contain only Note; provenance is generated by the store.
type AmountCorrectionValue struct {
	Amount   *float64           `json:"amount"`
	Currency string             `json:"currency"`
	Basis    *UsagePricingBasis `json:"basis,omitempty"`
}

type PlanChargeRef struct {
	ChannelID int64  `json:"channel_id"`
	Month     string `json:"month"`
}

type AmountCorrectionRequest struct {
	UsageIDs    []int64                `json:"usage_ids,omitempty"`
	UsageFilter *UsageFilter           `json:"usage_filter,omitempty"`
	PlanCharges []PlanChargeRef        `json:"plan_charges,omitempty"`
	Actual      *AmountCorrectionValue `json:"actual,omitempty"`
	Official    *AmountCorrectionValue `json:"official,omitempty"`
	PlanAmount  *AmountCorrectionValue `json:"plan_amount,omitempty"`
	Reason      string                 `json:"reason"`
	Operator    string                 `json:"operator"`
}

type AmountCorrectionTarget struct {
	Kind              string                `json:"kind"`         // usage or plan_charge
	ID                int64                 `json:"id,omitempty"` // usage ID or plan channel ID
	Month             string                `json:"month,omitempty"`
	Metric            string                `json:"metric"` // actual, official or plan
	Before            AmountCorrectionValue `json:"before"`
	After             AmountCorrectionValue `json:"after"`
	OriginalSignature string                `json:"original_signature"`
	FactSignature     string                `json:"fact_signature"`
	Revision          string                `json:"revision,omitempty"`
}

// AmountCorrectionImpact expresses original-currency totals separately, with
// unknown counts so clearing an amount cannot be mistaken for a zero charge.
type AmountCorrectionImpact struct {
	Metric        string             `json:"metric"`
	BeforeTotals  map[string]float64 `json:"before_totals"`
	AfterTotals   map[string]float64 `json:"after_totals"`
	BeforeUnknown int                `json:"before_unknown"`
	AfterUnknown  int                `json:"after_unknown"`
}

type AmountCorrectionPreview struct {
	ID              string                   `json:"id"`
	Kind            string                   `json:"kind"` // correction or revert
	RevertsChangeID string                   `json:"reverts_change_id,omitempty"`
	Operator        string                   `json:"operator"`
	Reason          string                   `json:"reason"`
	CreatedAt       time.Time                `json:"created_at"`
	ExpiresAt       time.Time                `json:"expires_at"`
	RecordCount     int                      `json:"record_count"`
	Targets         []AmountCorrectionTarget `json:"targets"`
	Impact          []AmountCorrectionImpact `json:"impact"`
	UsageFilter     *UsageFilter             `json:"usage_filter,omitempty"`
	SnapshotMaxID   int64                    `json:"snapshot_max_id"`
}

type AmountCorrectionChange struct {
	AmountCorrectionPreview
	AppliedAt  time.Time `json:"applied_at"`
	Source     string    `json:"source"`
	RevertedBy string    `json:"reverted_by,omitempty"`
}

func manualCorrectionValue(in AmountCorrectionValue, layer string, at time.Time, reason string, plan bool) (AmountCorrectionValue, error) {
	note := ""
	if in.Basis != nil {
		basis := *in.Basis
		note = basis.Note
		basis.Note = ""
		if !reflect.DeepEqual(basis, UsagePricingBasis{}) {
			return in, errors.New("basis input only permits note; manual provenance is generated by the store")
		}
	}
	if len(note) > 2000 {
		return in, errors.New("basis note is too long")
	}
	if plan {
		if err := validatePlanAmount(in.Amount, in.Currency); err != nil {
			return in, err
		}
	} else {
		u := Usage{ActualCost: in.Amount, Currency: in.Currency}
		if err := normalizeUsagePricing(&u); err != nil {
			return in, err
		}
		in.Currency = u.Currency
	}
	if layer == "" {
		layer = "manual"
	}
	in.Basis = &UsagePricingBasis{
		Method: "manual_correction", CalculatedAt: at,
		Resolution: PriceResolution{SourceKind: "manual_correction", Status: "manual", Layer: layer},
		Currency:   in.Currency, MissingReason: "manual amount; no calculated rate breakdown", Note: reason,
	}
	if note != "" {
		in.Basis.Note += "; " + note
	}
	return in, nil
}

func usageMoney(u Usage, metric string) AmountCorrectionValue {
	if metric == "actual" {
		return AmountCorrectionValue{Amount: u.ActualCost, Currency: u.Currency, Basis: u.ActualPricing}
	}
	return AmountCorrectionValue{Amount: u.OfficialValue, Currency: u.OfficialCurrency, Basis: u.OfficialPricing}
}

// All facts and arbitrary stored request/response fields are part of identity;
// neither the other monetary metric nor JSON serialization order is included.
func usageFactSignature(raw string) (string, error) {
	var fields map[string]json.RawMessage
	if err := json.Unmarshal([]byte(raw), &fields); err != nil {
		return "", err
	}
	for _, key := range []string{"id", "actual_cost", "currency", "actual_pricing", "official_value", "official_currency", "official_pricing"} {
		delete(fields, key)
	}
	canonical, err := json.Marshal(fields)
	if err != nil {
		return "", err
	}
	sum := sha256.Sum256(canonical)
	return hex.EncodeToString(sum[:]), nil
}

func moneyEqual(a, b AmountCorrectionValue) bool {
	// JSON equality ignores time.Location pointers and treats persisted and
	// in-memory representations identically, without rounding monetary values.
	x, _ := json.Marshal(a)
	y, _ := json.Marshal(b)
	return string(x) == string(y)
}

func originalMoneySignature(kind, facts string, value AmountCorrectionValue) string {
	if kind == "plan_charge" {
		value.Basis = nil
	}
	raw, _ := json.Marshal(struct {
		Facts string
		Value AmountCorrectionValue
	}{facts, value})
	sum := sha256.Sum256(raw)
	return hex.EncodeToString(sum[:])
}

func planMoneyInTx(ctx context.Context, tx *sql.Tx, id int64, month string) (AmountCorrectionValue, string, error) {
	var value AmountCorrectionValue
	var name string
	var paid int64
	err := tx.QueryRowContext(ctx, "SELECT amount,currency,channel_name,paid_at FROM plan_charges WHERE channel_id=? AND month=?", id, month).Scan(&value.Amount, &value.Currency, &name, &paid)
	if errors.Is(err, sql.ErrNoRows) {
		return value, "", ErrNotFound
	}
	if err != nil {
		return value, "", err
	}
	// Plan charges have no calculated table; correction provenance lives in the
	// immutable audit record, rather than inventing a request allocation.
	raw, _ := json.Marshal([]any{id, month, name, paid})
	sum := sha256.Sum256(raw)
	return value, hex.EncodeToString(sum[:]), nil
}

func correctionImpact(targets []AmountCorrectionTarget) []AmountCorrectionImpact {
	byMetric := map[string]*AmountCorrectionImpact{}
	for _, target := range targets {
		v := byMetric[target.Metric]
		if v == nil {
			v = &AmountCorrectionImpact{Metric: target.Metric, BeforeTotals: map[string]float64{}, AfterTotals: map[string]float64{}}
			byMetric[target.Metric] = v
		}
		if target.Before.Amount == nil {
			v.BeforeUnknown++
		} else {
			v.BeforeTotals[target.Before.Currency] += *target.Before.Amount
		}
		if target.After.Amount == nil {
			v.AfterUnknown++
		} else {
			v.AfterTotals[target.After.Currency] += *target.After.Amount
		}
	}
	out := []AmountCorrectionImpact{}
	for _, metric := range []string{"actual", "official", "plan"} {
		if v := byMetric[metric]; v != nil {
			out = append(out, *v)
		}
	}
	return out
}

func saveCorrectionPreview(ctx context.Context, tx *sql.Tx, p AmountCorrectionPreview) error {
	raw, err := json.Marshal(p)
	if err != nil {
		return err
	}
	_, err = tx.ExecContext(ctx, "INSERT INTO amount_correction_previews(id,data) VALUES(?,?)", p.ID, string(raw))
	return err
}

func (s *Store) PreviewAmountCorrection(ctx context.Context, req AmountCorrectionRequest) (AmountCorrectionPreview, error) {
	p := AmountCorrectionPreview{ID: uuid.NewString(), Kind: "correction", Operator: req.Operator, Reason: req.Reason, CreatedAt: time.Now().UTC(), Targets: []AmountCorrectionTarget{}, UsageFilter: req.UsageFilter}
	p.ExpiresAt = p.CreatedAt.Add(10 * time.Minute)
	if err := correctionText(req.Operator, "operator"); err != nil {
		return p, err
	}
	if err := correctionText(req.Reason, "reason"); err != nil {
		return p, err
	}
	if len(req.UsageIDs) > 0 && req.UsageFilter != nil {
		return p, errors.New("choose usage_ids or usage_filter")
	}
	if req.UsageFilter != nil {
		if err := validateManagementFilter(*req.UsageFilter); err != nil {
			return p, err
		}
		if req.UsageFilter.Limit != 0 {
			return p, errors.New("correction filters do not accept limit; use exact IDs for batches")
		}
	}
	if len(req.UsageIDs) > UsageManagementBatchLimit || len(req.PlanCharges) > UsageManagementBatchLimit {
		return p, errors.New("at most 1000 records per correction; split into explicit batches")
	}
	if (len(req.UsageIDs) > 0 || req.UsageFilter != nil) && req.Actual == nil && req.Official == nil {
		return p, errors.New("usage correction requires actual or official")
	}
	if len(req.UsageIDs) == 0 && req.UsageFilter == nil && (req.Actual != nil || req.Official != nil) {
		return p, errors.New("usage amounts require explicit targets")
	}
	if (len(req.PlanCharges) > 0) != (req.PlanAmount != nil) {
		return p, errors.New("plan_amount and plan_charges must be supplied together")
	}
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return p, err
	}
	defer tx.Rollback()
	ids := append([]int64{}, req.UsageIDs...)
	if err = tx.QueryRowContext(ctx, "SELECT COALESCE(MAX(id),0) FROM usage_logs").Scan(&p.SnapshotMaxID); err != nil {
		return p, err
	}
	if req.UsageFilter != nil {
		where, args := usageWhere(*req.UsageFilter)
		args = append(args, p.SnapshotMaxID, UsageManagementBatchLimit+1)
		rows, e := tx.QueryContext(ctx, "SELECT id FROM usage_logs"+where+" AND id<=? ORDER BY id LIMIT ?", args...)
		if e != nil {
			return p, e
		}
		for rows.Next() {
			var id int64
			if err = rows.Scan(&id); err != nil {
				break
			}
			ids = append(ids, id)
		}
		if err == nil {
			err = rows.Err()
		}
		rows.Close()
		if err != nil {
			return p, err
		}
	}
	if len(ids)+len(req.PlanCharges) > UsageManagementBatchLimit {
		return p, errors.New("correction matches more than 1000 records; page logs and submit explicit ID batches")
	}
	if len(ids)+len(req.PlanCharges) == 0 {
		return p, errors.New("correction has no targets")
	}
	sort.Slice(ids, func(i, j int) bool { return ids[i] < ids[j] })
	seen := map[string]bool{}
	for _, id := range ids {
		if id <= 0 || seen[fmt.Sprint(id)] {
			return p, errors.New("usage IDs must be positive and unique")
		}
		seen[fmt.Sprint(id)] = true
		u, raw, e := usageByIDInTx(ctx, tx, id)
		if e != nil {
			return p, e
		}
		if u.NotSent {
			return p, errors.New("not_sent facts cannot be priced by correction")
		}
		if req.Actual != nil && u.ActualPricing != nil && u.ActualPricing.Resolution.Layer == "plan" {
			return p, errors.New("unallocated plan request cost cannot become a per-request amount; correct the plan charge")
		}
		sig, e := usageFactSignature(raw)
		if e != nil {
			return p, e
		}
		for _, item := range []struct {
			metric string
			value  *AmountCorrectionValue
		}{{"actual", req.Actual}, {"official", req.Official}} {
			if item.value == nil {
				continue
			}
			before := usageMoney(u, item.metric)
			layer := ""
			if before.Basis != nil {
				layer = before.Basis.Resolution.Layer
			}
			after, e := manualCorrectionValue(*item.value, layer, p.CreatedAt, req.Reason, false)
			if e != nil {
				return p, e
			}
			revision, e := correctionRevision(ctx, tx, correctionTargetKey("usage", id, ""), item.metric)
			if e != nil {
				return p, e
			}
			p.Targets = append(p.Targets, AmountCorrectionTarget{Kind: "usage", ID: id, Metric: item.metric, Before: before, After: after, FactSignature: sig, OriginalSignature: originalMoneySignature("usage", sig, before), Revision: revision})
		}
	}
	for _, ref := range req.PlanCharges {
		if ref.ChannelID <= 0 {
			return p, errors.New("plan channel ID must be positive")
		}
		if err = ValidatePlanMonth(ref.Month); err != nil {
			return p, err
		}
		key := correctionTargetKey("plan_charge", ref.ChannelID, ref.Month)
		if seen[key] {
			return p, errors.New("duplicate plan charge")
		}
		seen[key] = true
		before, sig, e := planMoneyInTx(ctx, tx, ref.ChannelID, ref.Month)
		if e != nil {
			return p, e
		}
		after, e := manualCorrectionValue(*req.PlanAmount, "plan", p.CreatedAt, req.Reason, true)
		if e != nil {
			return p, e
		}
		revision, e := correctionRevision(ctx, tx, key, "plan")
		if e != nil {
			return p, e
		}
		p.Targets = append(p.Targets, AmountCorrectionTarget{Kind: "plan_charge", ID: ref.ChannelID, Month: ref.Month, Metric: "plan", Before: before, After: after, FactSignature: sig, OriginalSignature: originalMoneySignature("plan_charge", sig, before), Revision: revision})
	}
	p.RecordCount = len(ids) + len(req.PlanCharges)
	p.Impact = correctionImpact(p.Targets)
	if err = saveCorrectionPreview(ctx, tx, p); err != nil {
		return p, err
	}
	return p, tx.Commit()
}

func loadCorrectionPreview(ctx context.Context, tx *sql.Tx, id, operator string) (AmountCorrectionPreview, error) {
	var p AmountCorrectionPreview
	var raw string
	err := tx.QueryRowContext(ctx, "SELECT data FROM amount_correction_previews WHERE id=?", id).Scan(&raw)
	if errors.Is(err, sql.ErrNoRows) {
		return p, ErrNotFound
	}
	if err != nil {
		return p, err
	}
	if err = json.Unmarshal([]byte(raw), &p); err != nil {
		return p, err
	}
	if p.Operator != operator {
		return AmountCorrectionPreview{}, errors.New("correction preview belongs to a different operator")
	}
	return p, nil
}

func (s *Store) GetAmountCorrectionPreview(ctx context.Context, id, operator string) (AmountCorrectionPreview, error) {
	tx, err := s.db.BeginTx(ctx, &sql.TxOptions{ReadOnly: true})
	if err != nil {
		return AmountCorrectionPreview{}, err
	}
	defer tx.Rollback()
	p, err := loadCorrectionPreview(ctx, tx, id, operator)
	if err != nil {
		return p, err
	}
	return p, tx.Commit()
}

func loadCorrectionChange(ctx context.Context, tx *sql.Tx, id string) (AmountCorrectionChange, error) {
	var out AmountCorrectionChange
	var raw string
	err := tx.QueryRowContext(ctx, "SELECT data FROM amount_correction_changes WHERE id=?", id).Scan(&raw)
	if errors.Is(err, sql.ErrNoRows) {
		return out, ErrNotFound
	}
	if err != nil {
		return out, err
	}
	err = json.Unmarshal([]byte(raw), &out)
	return out, err
}

func (s *Store) GetAmountCorrection(ctx context.Context, id string) (AmountCorrectionChange, error) {
	tx, err := s.db.BeginTx(ctx, &sql.TxOptions{ReadOnly: true})
	if err != nil {
		return AmountCorrectionChange{}, err
	}
	defer tx.Rollback()
	out, err := loadCorrectionChange(ctx, tx, id)
	if err != nil {
		return out, err
	}
	return out, tx.Commit()
}

func checkCorrectionTarget(ctx context.Context, tx *sql.Tx, target AmountCorrectionTarget) error {
	var current AmountCorrectionValue
	var sig string
	var err error
	if target.Kind == "usage" {
		var u Usage
		var raw string
		u, raw, err = usageByIDInTx(ctx, tx, target.ID)
		if err != nil {
			return fmt.Errorf("%w: usage %d", ErrAmountCorrectionConflict, target.ID)
		}
		current = usageMoney(u, target.Metric)
		sig, err = usageFactSignature(raw)
	} else {
		current, sig, err = planMoneyInTx(ctx, tx, target.ID, target.Month)
	}
	if err != nil {
		return fmt.Errorf("%w: %s %d", ErrAmountCorrectionConflict, target.Kind, target.ID)
	}
	expected := target.Before
	if target.Kind == "plan_charge" {
		expected.Basis = nil
	}
	revision, err := correctionRevision(ctx, tx, correctionTargetKey(target.Kind, target.ID, target.Month), target.Metric)
	if err != nil {
		return err
	}
	if sig != target.FactSignature || originalMoneySignature(target.Kind, sig, current) != target.OriginalSignature || !moneyEqual(current, expected) || revision != target.Revision {
		return fmt.Errorf("%w: %s %d %s", ErrAmountCorrectionConflict, target.Kind, target.ID, target.Metric)
	}
	return nil
}

func writeCorrectionTarget(ctx context.Context, tx *sql.Tx, target AmountCorrectionTarget, changeID string) error {
	if target.Kind == "usage" {
		_, raw, err := usageByIDInTx(ctx, tx, target.ID)
		if err != nil {
			return err
		}
		var fields map[string]json.RawMessage
		if err = json.Unmarshal([]byte(raw), &fields); err != nil {
			return err
		}
		keys := []string{"actual_cost", "currency", "actual_pricing"}
		if target.Metric == "official" {
			keys = []string{"official_value", "official_currency", "official_pricing"}
		}
		for i, value := range []any{target.After.Amount, target.After.Currency, target.After.Basis} {
			fields[keys[i]], err = json.Marshal(value)
			if err != nil {
				return err
			}
		}
		encoded, err := json.Marshal(fields)
		if err != nil {
			return err
		}
		if _, err = tx.ExecContext(ctx, "UPDATE usage_logs SET data=? WHERE id=?", string(encoded), target.ID); err != nil {
			return err
		}
	} else {
		if _, err := tx.ExecContext(ctx, "UPDATE plan_charges SET amount=?,currency=? WHERE channel_id=? AND month=?", target.After.Amount, target.After.Currency, target.ID, target.Month); err != nil {
			return err
		}
	}
	_, err := tx.ExecContext(ctx, "INSERT INTO amount_correction_versions(target,metric,revision) VALUES(?,?,?) ON CONFLICT(target,metric) DO UPDATE SET revision=excluded.revision", correctionTargetKey(target.Kind, target.ID, target.Month), target.Metric, changeID)
	return err
}

// ApplyAmountCorrection is atomic and idempotent for the frozen preview ID.
// Callers must independently re-check current management authorization.
func (s *Store) ApplyAmountCorrection(ctx context.Context, previewID, operator string) (AmountCorrectionChange, error) {
	var out AmountCorrectionChange
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return out, err
	}
	defer tx.Rollback()
	if previous, e := loadCorrectionChange(ctx, tx, previewID); e == nil {
		if previous.Operator != operator {
			return out, errors.New("correction preview belongs to a different operator")
		}
		return previous, tx.Commit()
	} else if !errors.Is(e, ErrNotFound) {
		return out, e
	}
	p, err := loadCorrectionPreview(ctx, tx, previewID, operator)
	if err != nil {
		return out, err
	}
	if !time.Now().Before(p.ExpiresAt) {
		return out, fmt.Errorf("%w: preview expired", ErrAmountCorrectionConflict)
	}
	var reverted AmountCorrectionChange
	if p.Kind == "revert" {
		reverted, err = loadCorrectionChange(ctx, tx, p.RevertsChangeID)
		if err != nil {
			return out, err
		}
		if reverted.RevertedBy != "" {
			return out, ErrAmountCorrectionConflict
		}
	}
	for _, target := range p.Targets {
		if err = checkCorrectionTarget(ctx, tx, target); err != nil {
			return out, err
		}
	}
	for _, target := range p.Targets {
		if err = writeCorrectionTarget(ctx, tx, target, p.ID); err != nil {
			return out, err
		}
	}
	out = AmountCorrectionChange{AmountCorrectionPreview: p, AppliedAt: time.Now().UTC(), Source: "manual_correction"}
	raw, err := json.Marshal(out)
	if err != nil {
		return out, err
	}
	if _, err = tx.ExecContext(ctx, "INSERT INTO amount_correction_changes(id,data) VALUES(?,?)", out.ID, string(raw)); err != nil {
		return out, err
	}
	if p.Kind == "revert" {
		reverted.RevertedBy = p.ID
		raw, err = json.Marshal(reverted)
		if err != nil {
			return out, err
		}
		if _, err = tx.ExecContext(ctx, "UPDATE amount_correction_changes SET data=? WHERE id=?", string(raw), reverted.ID); err != nil {
			return out, err
		}
	}
	return out, tx.Commit()
}

func (s *Store) PreviewAmountRevert(ctx context.Context, changeID, operator, reason string) (AmountCorrectionPreview, error) {
	p := AmountCorrectionPreview{ID: uuid.NewString(), Kind: "revert", RevertsChangeID: changeID, Operator: operator, Reason: reason, CreatedAt: time.Now().UTC(), Targets: []AmountCorrectionTarget{}}
	p.ExpiresAt = p.CreatedAt.Add(10 * time.Minute)
	if err := correctionText(operator, "operator"); err != nil {
		return p, err
	}
	if err := correctionText(reason, "reason"); err != nil {
		return p, err
	}
	tx, err := s.db.BeginTx(ctx, nil)
	if err != nil {
		return p, err
	}
	defer tx.Rollback()
	change, err := loadCorrectionChange(ctx, tx, changeID)
	if err != nil {
		return p, err
	}
	if change.RevertedBy != "" {
		return p, ErrAmountCorrectionConflict
	}
	for _, target := range change.Targets {
		target.Before, target.After = target.After, target.Before
		target.OriginalSignature = originalMoneySignature(target.Kind, target.FactSignature, target.Before)
		target.Revision = change.ID
		if err = checkCorrectionTarget(ctx, tx, target); err != nil {
			return p, err
		}
		p.Targets = append(p.Targets, target)
	}
	p.RecordCount = change.RecordCount
	p.SnapshotMaxID = change.SnapshotMaxID
	p.Impact = correctionImpact(p.Targets)
	if err = saveCorrectionPreview(ctx, tx, p); err != nil {
		return p, err
	}
	return p, tx.Commit()
}
